class Solution {
    public int maxDepth(Node root) {
        if (root == null) {
            return 0;
        }

        int maxChildDepth = 0;
        for (Node child : root.children) {
            maxChildDepth = Math.max(maxChildDepth, maxDepth(child));
        }
        return maxChildDepth + 1;
    }
}

class Solution {
    public int maxDepth(Node root) {
        if (root == null) {
            return 0;
        }

        java.util.Queue<Node> queue = new java.util.LinkedList<>();
        queue.offer(root);
        int depth = 0;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            depth++;
            for (int i = 0; i < levelSize; i++) {
                Node node = queue.poll();
                for (Node child : node.children) {
                    queue.offer(child);
                }
            }
        }

        return depth;
    }
}

class Solution {
    public int maxDepth(Node root) {
        if (root == null) {
            return 0;
        }

        java.util.ArrayDeque<Node> nodeStack = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Integer> depthStack = new java.util.ArrayDeque<>();
        nodeStack.push(root);
        depthStack.push(1);
        int best = 0;

        while (!nodeStack.isEmpty()) {
            Node node = nodeStack.pop();
            int depth = depthStack.pop();
            best = Math.max(best, depth);

            for (Node child : node.children) {
                nodeStack.push(child);
                depthStack.push(depth + 1);
            }
        }

        return best;
    }
}

class Solution {
    public int maxDepth(Node root) {
        if (root == null) {
            return 0;
        }

        java.util.ArrayDeque<Node> traversal = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Node> postorder = new java.util.ArrayDeque<>();
        traversal.push(root);

        while (!traversal.isEmpty()) {
            Node node = traversal.pop();
            postorder.push(node);
            for (Node child : node.children) {
                traversal.push(child);
            }
        }

        java.util.HashMap<Node, Integer> height = new java.util.HashMap<>();
        while (!postorder.isEmpty()) {
            Node node = postorder.pop();
            int maxChildDepth = 0;
            for (Node child : node.children) {
                maxChildDepth = Math.max(maxChildDepth, height.get(child));
            }
            height.put(node, maxChildDepth + 1);
        }

        return height.get(root);
    }
}
